// Normalize the payload sent by Moonday (admin approval or the scheduled
// dispatcher). Accepts both shapes: `substack_post` (approval) and
// `body`/`content` (auto dispatcher).
const p = $json.body || $json;

const body = String(p.substack_post || p.body || p.content || '').trim();
if (!body) {
  throw new Error('Missing Substack copy in payload');
}

const title = p.title || 'Moonday Transit';
const sign = p.zodiac_sign_tag || p.zodiac_sign || '';
const image = p.image_url || '';
const slug = p.slug || '';
const canonical = p.canonical || p.source_url || (slug ? `https://moondaylive.com/blog/${slug}` : 'https://moondaylive.com/blog');

// Inline HTML image block. Moonday already sends a ready-made `image_html`;
// fall back to building it here so older payloads still render the PNG.
const imageHtml = p.image_html || (image
  ? `<img src="${image}" alt="${sign || title}" width="600" style="display:block;margin:0 auto 24px;max-width:100%;height:auto;" />`
  : '');

// Substack's email-to-post ingestion keeps inline HTML, so the hero PNG
// always appears at the top of the published post.
const paragraphs = body
  .split(/\n{2,}/)
  .map((chunk) => chunk.trim())
  .filter(Boolean)
  .map((chunk) => `<p>${chunk.replace(/\n/g, '<br />')}</p>`)
  .join('\n');

const html = `${imageHtml}\n${paragraphs}\n<p><a href="${canonical}">Read this transit on Moonday Live</a></p>`;

return [{
  json: {
    post_id: p.post_id || null,
    slug,
    title,
    sign,
    excerpt: p.excerpt || '',
    image_url: image,
    image_html: imageHtml,
    publish_at: p.publish_at || p.scheduled_time || null,
    sent_at: p.sent_at || new Date().toISOString(),
    subject: title,
    markdown: (image ? `![${sign || title}](${image})\n\n` : '') + body,
    html,
    canonical
  }
}];
